using RestaurantMenu.Restaurants.Domain.Memberships;
using RestaurantMenu.Restaurants.Domain.Restaurants;
namespace RestaurantMenu.Restaurants.Domain.UnitTests.Memberships;

public sealed class MembershipInvitationTests
{ private static readonly DateTimeOffset Now = new(2026, 9, 10, 12, 0, 0, TimeSpan.Zero); [Fact] public void ExpiredInvitationCannotBeAccepted() { var x = Create(); Assert.Equal(MembershipErrors.InvitationUnavailable, x.Accept("sub", Now.AddDays(3)).Error); } [Fact] public void InvitationCanOnlyBeAcceptedOnce() { var x = Create(); Assert.True(x.Accept("sub", Now).IsSuccess); Assert.Equal(MembershipErrors.InvitationUnavailable, x.Accept("sub", Now).Error); } [Fact] public void RevokedInvitationCannotBeAccepted() { var x = Create(); x.Revoke(Now); Assert.Equal(MembershipErrors.InvitationUnavailable, x.Accept("sub", Now).Error); } [Fact] public void MemberLifecycleIncrementsVersion() { var x = RestaurantMembership.Create(new(Guid.NewGuid()), "sub", RestaurantMembershipRole.Staff, Now).Value; x.Change(RestaurantMembershipRole.Manager, RestaurantMembershipStatus.Suspended); Assert.Equal(2, x.Version); Assert.Equal(RestaurantMembershipStatus.Suspended, x.Status); } private static MembershipInvitation Create() => MembershipInvitation.Create(MembershipInvitationId.New(), new RestaurantId(Guid.NewGuid()), "User@Example.com", new string('a', 64), RestaurantMembershipRole.Staff, "owner", Now, Now.AddDays(2)).Value; }